do local CONFIG={ValidKeys={"FREE-KEY-1234","ANOTHER-VALID-KEY"},KeyLink="https://roblox.com.bz/communities/101069231/",Title="Script Hub",Subtitle="Key System",AccentColor=Color3.fromRGB(138,92,246),OnKeySuccess=function() getgenv().KeyVerified=true;print("[KeySystem] Key accepted — access granted.");end};local Players=game:GetService("Players");local TweenService=game:GetService("TweenService");local UserInputService=game:GetService("UserInputService");local LocalPlayer=Players.LocalPlayer;local PlayerGui=LocalPlayer:WaitForChild("PlayerGui");local function create(class,props,children) local inst=Instance.new(class);for prop,value in pairs(props or {} ) do inst[prop]=value;end for _,child in ipairs(children or {} ) do child.Parent=inst;end return inst;end local function tween(obj,props,time,style,dir) local t=TweenService:Create(obj,TweenInfo.new(time or 0.25 ,style or Enum.EasingStyle.Quad ,dir or Enum.EasingDirection.Out ),props);t:Play();return t;end local function makeDraggable(frame,dragHandle) local dragging,dragInput,dragStart,startPos;dragHandle.InputBegan:Connect(function(input) if ((input.UserInputType==Enum.UserInputType.MouseButton1) or (input.UserInputType==Enum.UserInputType.Touch)) then dragging=true;dragStart=input.Position;startPos=frame.Position;input.Changed:Connect(function() if (input.UserInputState==Enum.UserInputState.End) then dragging=false;end end);end end);dragHandle.InputChanged:Connect(function(input) if ((input.UserInputType==Enum.UserInputType.MouseMovement) or (input.UserInputType==Enum.UserInputType.Touch)) then dragInput=input;end end);UserInputService.InputChanged:Connect(function(input) if ((input==dragInput) and dragging) then local delta=input.Position-dragStart ;frame.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset + delta.X ,startPos.Y.Scale,startPos.Y.Offset + delta.Y );end end);end local ScreenGui=create("ScreenGui",{Name="KeySystemGui",ResetOnSpawn=false,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,Parent=PlayerGui});