or},0.15);end);end bindHover(CheckButton,CONFIG.AccentColor,Color3.fromRGB(158,112,255));bindHover(CopyButton,Color3.fromRGB(40,40,50),Color3.fromRGB(52,52,64));CheckButton.MouseButton1Click:Connect(function() local entered=KeyBox.Text;local isValid=false;for _,validKey in ipairs(CONFIG.ValidKeys) do if (entered==validKey) then isValid=true;break;end end if isValid then StatusLabel.TextColor3=Color3.fromRGB(120,255,150);StatusLabel.Text="✔ Key accepted! Loading...";tween(InputHolder,{BackgroundColor3=Color3.fromRGB(30,46,34)},0.2);task.spawn(function() local ok,err=pcall(CONFIG.OnKeySuccess);if  not ok then warn("[KeySystem] OnKeySuccess error: "   .. tostring(err) );end end);task.wait(0.6);tween(Main,{Size=UDim2.new(0,380,0,0)},0.25);task.wait(0.25);ScreenGui:Destroy();else StatusLabel.TextColor3=Color3.fromRGB(255,120,120);StatusLabel.Text="✘ Invalid key. Try again.";tween(InputHolder,{BackgroundColor3=Color3.fromRGB(46,30,34)},0.15);task.wait(0.15);tween(InputHolder,{BackgroundColor3=Color3.fromRGB(32,32,42)},0.25);end end);CopyButton.MouseButton1Click:Connect(function() local success=pcall(function() setclipboard(CONFIG.KeyLink);end);if success then local originalText=CopyButton.Text;CopyButton.Text="Copied!";StatusLabel.TextColor3=Color3.fromRGB(120,200,255);StatusLabel.Text="Link copied to clipboard.";task.wait(1);CopyButton.Text=originalText;else StatusLabel.TextColor3=Color3.fromRGB(255,120,120);StatusLabel.Text="Your executor doesn't support setclipboard.";end end);Main.Size=UDim2.new(0,380,0,0);tween(Main,{Size=UDim2.new(0,380,0,220)},0.35,Enum.EasingStyle.Back); end